	"    float contactAO = isGrassMesh ? mix(0.55, 1.0, smoothstep(0.0, 3.6, vHeightAboveGround))\n"
	"                                : mix(0.56, 1.0, smoothstep(0.0, 5.2, vHeightAboveGround));\n"
	"    float cavityAO = isFoliage ? mix(0.22, 1.06, vAOc) : mix(0.46, 1.06, vAOc);\n"
	"    float sunSelfShadow = (isFoliage ? mix(0.10, 1.0, smoothstep(0.24, 0.82, vAOc)) : mix(0.32, 1.0, smoothstep(0.18, 0.72, vAOc))) * selfShadowVis;\n"
	"    float ao = isFoliage ? clamp(cavityAO * contactAO * microAO, 0.16, 1.14)\n"
	"                         : clamp(cavityAO * contactAO * microAO, 0.38, 1.14);\n"
	"    float dirRelief = mix(0.22 + 0.78 * dayFactor, 1.0, directSun);\n"
	"    vec3 lightTerm = (ambCol * (0.36 * nd_amb_trans(cloudSh) * (0.20 + 0.80 * dayFactor)) +\n"
	"                      vec3(0.80 * diff * sunTrans * dirRelief * sunSelfShadow) +\n"
	"                      vec3(torusShine)) * ao * sunLitCol * shadowCool;\n"
	"    vec3 lit = albedo * lightTerm;\n"
	"    /* Physical Subsurface Transmittance (outer sunlit rims only) & Schlick Fresnel Specular */\n"
	"    vec3 H_local = normalize(L_local + V_local);\n"
	"    float specAngle = max(0.0, dot(N_local, H_local));\n"
	"    float ndotv = max(0.0, dot(N_local, V_local));\n"
	"    if (isFoliage || isFlower) {\n"
	"        float backTrans = max(0.0, dot(-N_local, L_local) + 0.34);\n"
	"        float viewBack  = pow(max(0.0, dot(-V_local, L_local)), 3.0);\n"
	"        float rimTrans  = (1.0 - ndotv) * max(0.0, L_local.z);\n"
	"        float coreSss = isFolCore ? (isGrassMesh ? (0.35 + 0.55 * smoothstep(2.0, 7.5, vHeightAboveGround)) : 0.36) : 1.0;\n"
	"        float outerSssMask = smoothstep(0.36, 0.92, vAOc);\n"
	"        float sss = (0.48 * backTrans + 0.32 * rimTrans + 0.55 * viewBack) * outerSssMask * coreSss * (hasBrCard ? (0.22 + 1.12 * brTrans) : 1.0);\n"
	"        lit += albedo * vec3(0.19894, 0.40086, 0.01774) * (sss * 0.64 * selfShadowVis * sunTrans * directSun * sunLitCol) * distFade;\n"
	"        float leafFresnel = 0.04 + 0.22 * pow(1.0 - ndotv, 4.0);\n"
	"        lit += mix(albedo, vec3(1.0, 0.97813, 0.83240), 0.35) * (pow(specAngle, 20.0) * leafFresnel * 0.40 * sunSelfShadow * sunTrans * directSun * sunLitCol) * distFade;\n"
	"    } else if (isCrystal) {\n"
	"        float f0 = 0.06;\n"
	"        float fresnel = f0 + (1.0 - f0) * pow(clamp(1.0 - ndotv, 0.0, 1.0), 5.0);\n"
	"        float spec = pow(specAngle, 48.0) * 0.72 * nd_sun_trans(cloudSh) * directSun * selfShadowVis;\n"
	"        float internalGlow = max(0.0, dot(-N_local, L_local) + 0.50) * 0.28 * directSun;\n"
	"        lit += vec3(1.0, 0.97813, 0.89329) * spec * distFade + albedo * (fresnel * 0.38 + internalGlow);\n"
	"    } else if (isRock) {\n"
	"        float micaSparkle = pow(specAngle, 28.0) * 0.20 * nd_sun_trans(cloudSh) * directSun * selfShadowVis;\n"
	"        lit += vec3(micaSparkle * distFade);\n"
	"    }\n"
	"    /* Warm point-light illumination from the glowing Lamb */\n"
	"    if (uLambLight.w > 0.001) {\n"
	"        vec3 toLamb = vec3(uLambLight.x - vLocalPos.x, uLambLight.y - vLocalPos.y, uLambLight.z + 10.0 - vLocalPos.z);\n"
	"        float d2 = dot(toLamb, toLamb);\n"
	"        float atten = (1.0 / (1.0 + d2 * 0.00055)) * (1.0 - smoothstep(28.0 * 28.0, 220.0 * 220.0, d2));\n"
	"        float dirFactor = (d2 > 1e-4) ? clamp(0.40 + 0.60 * dot(N_local, toLamb * inversesqrt(d2)), 0.20, 1.0) : 1.0;\n"
	"        vec3 warmGlow = vec3(1.13677, 0.97813, 0.68142) * (uLambLight.w * 0.26 * atten * dirFactor);\n"
	"        lit += (albedo * 0.72 + vec3(0.28)) * warmGlow;\n"
	"    }\n"
	"    if (isSubmerged) {\n"
	"        float subRamp = smoothstep(0.0, 0.35, dWater);\n"
	"        vec3 absorb = exp(-vec3(0.075, 0.018, 0.0055) * (0.55 + dWater * 1.35) * subRamp);\n"
	"        lit = mix(lit * absorb, vec3(0.00386, 0.08153, 0.16428), subRamp * 0.35);\n"
	"    }\n"
	"    vec3 surfaceLit = mix(lit, vec3(0.09930, 0.38762, 0.89329), 0.22 * uAtmoIntensity);\n"
	"    surfaceLit = nd_eval_valley_fog(surfaceLit, vLocalPos.xy, vLocalPos.z, uSeaLevel, vDist, uAnimTime, dayFactor, sky, uAtmoIntensity);\n"
	"    vec3 finalRgb = mix(surfaceLit, sky, fogFactor * uAtmoIntensity);\n"
	"    FragColor = vec4(finalRgb, isSubmerged ? 0.0 : (vTint.a < 0.995 ? 1.0 : vTint.a));\n"
	"}\n";

